head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > M > setTabHTML]<br/>Tabs ID 값을 사용하여 특정 Tab 페이지의 Tabs tabHTML 속성을 설정합니다.",
    "validation" : [
        "Tabs tabHTML 속성 설정 시 Tabs label 속성은 무시됩니다.",
        "tabId(필수) 파라미터로 Tab 버튼의 라벨을 설정하려는 Tab 페이지의 Tabs ID 를 설정합니다.",
        "tabHTML(필수) 파라미터로 Tab 버튼의 라벨로 표시할 HTML 코드 또는 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수는 Tabs 의 label 속성값을 파라미터로 전달 받습니다.",
        "사용자 정의 함수의 반환값이 Tab 버튼의 라벨로 표시됩니다.",
        "Tabs 의 tabType 속성값에 관계없이 tabHTML 속성이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // $c.gcm.createBasicTabControl();
    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs tabType="image" selectedImage="/img/png.png" disabled="false" style="width:150px; height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs tabType="text" disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



// 사용자 정의 함수로 설정
scwin.set_tabHtml = function(label) {
    return '<input type="button" value="' + label + '_userFunc">';
};



scwin.btn_getTabHTML_onclick = function (e) {      
    const tabIds = [
        'target1_tab_tabs1_tabHTML',
        'target1_tab_tabs2_tabHTML',
        'target1_tab_tabs3_tabHTML'
    ];

    tabIds.forEach((tabId, index) => {
        let tabHTML = document.querySelector(`[id*=${tabId}]`);

        if (tabHTML) {
            let input = tabHTML.querySelector('input');

            if (input) {
                wf_body_bottom.getObj("scwin").setReturnValue(`tabHTML${index+1} tagName : ${input.tagName}`);
                wf_body_bottom.getObj("scwin").setReturnValue(`tabHTML${index+1} label : ${input.value}`);
            }
        }
    });  
}



scwin.btn_setTabHTML_onclick = function (e) {
    let tabId = par_tabId.getText();
    let tabHTML = par_tabHTML.getText();
    let value = tabId + "_HTML";

    if (tabHTML == "HTML 코드")
        target1.setTabHTML(tabId, `<input type="button" value="${value}">`);
    else if (tabHTML == "사용자 정의 함수")
        target1.setTabHTML(tabId, 'scwin.set_tabHtml');

    scwin.btn_getTabHTML_onclick();
};
